// Edge Function "login" as a single file for the Supabase dashboard editor.
// Generated by scripts/build-dashboard-functions.mjs from supabase/functions/. Do not edit by hand.
// In the dashboard: Edge Functions -> Deploy a new function -> Via Editor -> name it "login",
// paste this whole file, Deploy, then switch "Verify JWT" OFF for it (this function checks the caller itself).

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2';

// ---- _shared\deps.ts
// Dependency container so handlers can be unit-tested with fakes.

interface Deps {
  env: (name: string) => string | undefined;
  /** Client acting as the logged-in user (RLS applies, auth.uid() is set). */
  userClient: (token: string) => SupabaseClient;
  /** Client with only the public anon key (for verifying a password like the browser would). */
  anon: () => SupabaseClient;
  /** Service-role client. Only for work the user must not do themselves (storage, auth admin). */
  admin: () => SupabaseClient;
  fetch: typeof fetch;
  /** Run work after the response is sent (EdgeRuntime.waitUntil); awaited inline if unavailable. */
  background: (work: Promise<unknown>) => void;
  now: () => Date;
}

function need(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`Missing function secret: ${name}`);
  return v;
}

function realDeps(): Deps {
  let admin: SupabaseClient | undefined;
  return {
    env: (n) => Deno.env.get(n),
    userClient: (token) =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        global: { headers: { Authorization: `Bearer ${token}` } },
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    anon: () =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    admin: () =>
      (admin ??= createClient(need('SUPABASE_URL'), need('SUPABASE_SERVICE_ROLE_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      })),
    fetch: (...a) => fetch(...a),
    background: (work) => {
      // deno-lint-ignore no-explicit-any
      const rt = (globalThis as any).EdgeRuntime;
      const guarded = work.catch((e) => console.error('background task failed', e instanceof Error ? e.message : e));
      if (rt?.waitUntil) rt.waitUntil(guarded);
    },
    now: () => new Date(),
  };
}

/** Verifies the bearer token with Supabase Auth and returns the user id. */
async function authenticate(deps: Deps, token: string | null): Promise<{ id: string; email?: string } | null> {
  if (!token) return null;
  const { data, error } = await deps.admin().auth.getUser(token);
  if (error || !data?.user) return null;
  return { id: data.user.id, email: data.user.email };
}

// ---- _shared\http.ts
// Small HTTP helpers shared by all Edge Functions.
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

/** Handles CORS preflight and non-POST methods. Returns a Response when the request is done. */
function gate(req: Request): Response | null {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed', message: 'Use POST.' }, 405);
  return null;
}

function bearer(req: Request): string | null {
  const h = req.headers.get('Authorization') ?? '';
  const m = /^Bearer\s+(.+)$/i.exec(h);
  return m ? m[1].trim() : null;
}

async function readJson(req: Request): Promise<Record<string, unknown> | null> {
  try {
    const body = await req.json();
    return body && typeof body === 'object' && !Array.isArray(body) ? body : null;
  } catch {
    return null;
  }
}

const STATUS_BY_CODE: Record<string, number> = {
  forbidden: 403, not_member: 403, not_found: 404, draft_not_found: 404,
  already_reviewed: 409, duplicate_reference: 409, resubmission_exists: 409, rate_limited: 429,
};

/**
 * Database errors are raised as "code: human message" (see the migrations). Known codes are passed
 * to the client; anything else is hidden behind a generic message.
 */
function dbError(error: { message?: string; code?: string; status?: number }): Response {
  const msg = error.message ?? '';
  if (error.code === 'PGRST301' || error.code === 'PGRST303' || /\bJWT\b/.test(msg)) {
    return json({ error: 'unauthorized', message: 'Please log in again.' }, 401);
  }
  const m = /^([a-z_]+): ([\s\S]*)$/.exec(msg);
  if (m) return json({ error: m[1], message: m[2] }, STATUS_BY_CODE[m[1]] ?? 400);
  if (error.code === '42501') return json({ error: 'forbidden', message: 'Not allowed.' }, 403);
  console.error('unexpected database error', error.code, msg);
  return json({ error: 'internal', message: 'Something went wrong. Please try again.' }, 500);
}

function errorResponse(code: string, message: string, status = 400): Response {
  return json({ error: code, message }, status);
}

// ---- _shared\key.ts
// Member login keys: remove all whitespace and dashes, uppercase.
// MUST match apps-script/Keys.gs and web/lib/key.ts (all three have a test for "k7rm-qx4p 9wab").
function normalizeKey(input: unknown): string {
  return String(input ?? '').replace(/[\s-]/g, '').toUpperCase();
}

// ---- login\handler.ts
// Login with a growing delay after repeated failures (1st wrong try free, 2nd starts a 180 s cooldown,
// then +1 minute per further failure, max 30 minutes). The numbers live in _login_lock_seconds (SQL).
// The website logs in through this function instead of calling Supabase Auth directly, so the failure
// count lives in the database and cannot be reset by clearing the browser. (Someone who calls the
// Supabase Auth API directly bypasses it; enabling the Auth password-verification hook applies the
// same rule there too. Then set the function secret LOGIN_THROTTLE_HOOK=on so failures are not counted twice.)



const BAD = 'Email or key is incorrect.';
type ThrottleState =
  | { locked: false; retry_after_seconds?: number }
  | { locked: true; retry_after_seconds: number };

function isThrottleState(value: unknown): value is ThrottleState {
  if (typeof value !== 'object' || value === null || !('locked' in value) || typeof value.locked !== 'boolean') {
    return false;
  }
  return value.locked
    ? 'retry_after_seconds' in value && typeof value.retry_after_seconds === 'number'
    : true;
}

function waitText(seconds: number): string {
  const minutes = Math.max(1, Math.ceil(seconds / 60));
  return `${minutes} minute${minutes === 1 ? '' : 's'}`;
}

function locked(seconds: number, prefix = ''): Response {
  return json({
    error: 'locked',
    retry_after_seconds: seconds,
    message: `${prefix}Too many failed attempts. Try again in ${waitText(seconds)}.`,
  }, 429);
}

async function handle(req: Request, deps: Deps): Promise<Response> {
  const early = gate(req);
  if (early) return early;

  const body = await readJson(req);
  const mode = body?.mode;
  if (typeof body?.email !== 'string' || typeof body?.password !== 'string' || (mode !== 'member' && mode !== 'admin')) {
    return errorResponse('bad_request', 'Email and key are required.');
  }
  const email = body.email.trim().toLowerCase();
  const password = mode === 'member' ? normalizeKey(body.password) : body.password;
  if (!/^[^@\s]+@[^@\s]+$/.test(email) || email.length > 254 || password.length === 0 || password.length > 200) {
    return errorResponse('invalid_credentials', BAD, 401);
  }

  const admin = deps.admin();
  let state: ThrottleState | null;
  let checkErr: { message: string; code?: string } | null;
  try {
    ({ data: state, error: checkErr } = await admin.rpc('login_check', { p_email: email }));
  } catch (error) {
    console.error('login: login_check RPC threw an exception', {
      code: errorCode(error),
      message: errorMessage(error),
    });
    return errorResponse('internal', 'Could not verify login throttling. Please try again.', 500);
  }
  if (checkErr) {
    console.error('login: login_check RPC failed', { code: checkErr.code, message: checkErr.message });
    return errorResponse('internal', 'Could not verify login throttling. Please try again.', 500);
  }
  if (!isThrottleState(state)) {
    console.error('login: login_check RPC returned an invalid throttling state', { data: state });
    return errorResponse('internal', 'Could not verify login throttling. Please try again.', 500);
  }
  if (state.locked) return locked(state.retry_after_seconds);   // not even tried: the right key does not help

  const { data, error } = await deps.anon().auth.signInWithPassword({ email, password });
  const hookCounts = deps.env('LOGIN_THROTTLE_HOOK') === 'on';   // Auth already records every attempt

  if (error || !data?.session) {
    if (error?.status === 429) {   // Supabase's own per-IP limit: not a wrong key, so do not count it
      return errorResponse('rate_limited', 'Too many attempts from your network. Wait a few minutes and try again.', 429);
    }
    if (hookCounts) return errorResponse('invalid_credentials', BAD, 401);
    let after: ThrottleState | null;
    let recordErr: { message: string; code?: string } | null;
    try {
      ({ data: after, error: recordErr } = await admin.rpc('login_record', { p_email: email, p_success: false }));
    } catch (recordError) {
      console.error('login: login_record RPC threw while recording a failed attempt', {
        code: errorCode(recordError),
        message: errorMessage(recordError),
      });
      return errorResponse('internal', 'Could not record the failed login attempt. Please try again.', 500);
    }
    if (recordErr) {
      console.error('login: login_record RPC failed while recording a failed attempt', {
        code: recordErr.code,
        message: recordErr.message,
      });
      return errorResponse('internal', 'Could not record the failed login attempt. Please try again.', 500);
    }
    if (!isThrottleState(after)) {
      console.error('login: login_record RPC returned an invalid state after a failed attempt', { data: after });
      return errorResponse('internal', 'Could not record the failed login attempt. Please try again.', 500);
    }
    if (after.locked) return locked(after.retry_after_seconds, `${BAD} `);
    return errorResponse('invalid_credentials', BAD, 401);
  }

  if (!hookCounts) {
    try {
      const { data: resetState, error: recordErr } = await admin.rpc('login_record', { p_email: email, p_success: true });
      if (recordErr) {
        console.error('login: login_record RPC failed while clearing successful-login failures', {
          code: recordErr.code,
          message: recordErr.message,
        });
        return errorResponse('internal', 'Login succeeded, but the throttling state could not be cleared. Please try again.', 500);
      }
      if (!isThrottleState(resetState) || resetState.locked) {
        console.error('login: login_record RPC returned an invalid state while clearing successful-login failures', {
          data: resetState,
        });
        return errorResponse('internal', 'Login succeeded, but the throttling state could not be cleared. Please try again.', 500);
      }
    } catch (recordError) {
      console.error('login: login_record RPC threw while clearing successful-login failures', {
        code: errorCode(recordError),
        message: errorMessage(recordError),
      });
      return errorResponse('internal', 'Login succeeded, but the throttling state could not be cleared. Please try again.', 500);
    }
  }
  return json({ session: { access_token: data.session.access_token, refresh_token: data.session.refresh_token } });
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error !== null && 'message' in error) return String(error.message);
  return String(error);
}

function errorCode(error: unknown): string | undefined {
  if (typeof error === 'object' && error !== null && 'code' in error) return String(error.code);
  return undefined;
}

// ---- login\index.ts
const deps = realDeps();
Deno.serve((req) => handle(req, deps));
